            FfiConverterOptionalTypeUuid.read(buf),
            FfiConverterTypeDateTime.read(buf),
        )
    }

    override fun allocationSize(value: WalletTransaction) = (
            FfiConverterTypeUuid.allocationSize(value.`id`) +
            FfiConverterTypeUuid.allocationSize(value.`walletId`) +
            FfiConverterTypeMoney.allocationSize(value.`amount`) +
            FfiConverterString.allocationSize(value.`description`) +
            FfiConverterOptionalTypeUuid.allocationSize(value.`relatedEntityId`) +
            FfiConverterTypeDateTime.allocationSize(value.`timestamp`)
    )

    override fun write(value: WalletTransaction, buf: ByteBuffer) {
            FfiConverterTypeUuid.write(value.`id`, buf)
            FfiConverterTypeUuid.write(value.`walletId`, buf)
            FfiConverterTypeMoney.write(value.`amount`, buf)
            FfiConverterString.write(value.`description`, buf)
            FfiConverterOptionalTypeUuid.write(value.`relatedEntityId`, buf)
            FfiConverterTypeDateTime.write(value.`timestamp`, buf)
    }
}





sealed class AppException(message: String): kotlin.Exception(message) {
        
        class Authentication(message: String) : AppException(message)
        
        class Authorization(message: String) : AppException(message)
        
        class NotFound(message: String) : AppException(message)
        
        class InsufficientStock(message: String) : AppException(message)
        
        class InsufficientFunds(message: String) : AppException(message)
        
        class Validation(message: String) : AppException(message)
        
        class Duplicate(message: String) : AppException(message)
        
        class DeletionBlocked(message: String) : AppException(message)
        
        class SyncConflict(message: String) : AppException(message)
        
        class Network(message: String) : AppException(message)
        
        class Database(message: String) : AppException(message)
        
        class Serialization(message: String) : AppException(message)
        
        class Unknown(message: String) : AppException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeAppError : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        
            return when(buf.getInt()) {
            1 -> AppException.Authentication(FfiConverterString.read(buf))
            2 -> AppException.Authorization(FfiConverterString.read(buf))
            3 -> AppException.NotFound(FfiConverterString.read(buf))
            4 -> AppException.InsufficientStock(FfiConverterString.read(buf))
            5 -> AppException.InsufficientFunds(FfiConverterString.read(buf))
            6 -> AppException.Validation(FfiConverterString.read(buf))
            7 -> AppException.Duplicate(FfiConverterString.read(buf))
            8 -> AppException.DeletionBlocked(FfiConverterString.read(buf))
            9 -> AppException.SyncConflict(FfiConverterString.read(buf))
            10 -> AppException.Network(FfiConverterString.read(buf))
            11 -> AppException.Database(FfiConverterString.read(buf))
            12 -> AppException.Serialization(FfiConverterString.read(buf))
            13 -> AppException.Unknown(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: AppException): ULong {
        return 4UL
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
            is AppException.Authentication -> {
                buf.putInt(1)
                Unit
            }
            is AppException.Authorization -> {
                buf.putInt(2)
                Unit
            }
            is AppException.NotFound -> {
                buf.putInt(3)
                Unit
            }
            is AppException.InsufficientStock -> {
                buf.putInt(4)
                Unit
            }
            is AppException.InsufficientFunds -> {
                buf.putInt(5)
                Unit
            }
            is AppException.Validation -> {
                buf.putInt(6)
                Unit
            }
            is AppException.Duplicate -> {
                buf.putInt(7)
                Unit
            }
            is AppException.DeletionBlocked -> {
                buf.putInt(8)
                Unit
            }
            is AppException.SyncConflict -> {
                buf.putInt(9)
                Unit
            }
            is AppException.Network -> {
                buf.putInt(10)
                Unit
            }
            is AppException.Database -> {
                buf.putInt(11)
                Unit
            }
            is AppException.Serialization -> {
                buf.putInt(12)
                Unit
            }
            is AppException.Unknown -> {
                buf.putInt(13)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




