    override fun write(value: List<WalletTransaction>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeWalletTransaction.write(it, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterMapTypeUuidDouble: FfiConverterRustBuffer<Map<Uuid, kotlin.Double>> {
    override fun read(buf: ByteBuffer): Map<Uuid, kotlin.Double> {
        val len = buf.getInt()
        return buildMap<Uuid, kotlin.Double>(len) {
            repeat(len) {
                val k = FfiConverterTypeUuid.read(buf)
                val v = FfiConverterDouble.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<Uuid, kotlin.Double>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterTypeUuid.allocationSize(k) +
            FfiConverterDouble.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<Uuid, kotlin.Double>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterTypeUuid.write(k, buf)
            FfiConverterDouble.write(v, buf)
        }
    }
}



